package com.andye.warmod.item.component;import com.andye.warmod.item.ModItems;import com.andye.warmod.rocket.RocketPayloadType;import com.mojang.serialization.Codec;import net.minecraft.world.item.Item;public enum RocketLauncherMode {HE,CONVENTIONAL,NUCLEAR;public static final Codec<RocketLauncherMode> CODEC=Codec.STRING.xmap(s->{try{return valueOf(s.toUpperCase(java.util.Locale.ROOT));}catch(IllegalArgumentException e){return HE;}},m->m.name().toLowerCase(java.util.Locale.ROOT));public RocketLauncherMode next(){return values()[(ordinal()+1)%values().length];}public Item ammunition(){return switch(this){case HE->ModItems.HE_ROCKET;case CONVENTIONAL->ModItems.CONVENTIONAL_ICBM;case NUCLEAR->ModItems.NUCLEAR_ICBM;};}public RocketPayloadType payload(){return switch(this){case HE->RocketPayloadType.HE;case CONVENTIONAL->RocketPayloadType.CONVENTIONAL_ICBM;case NUCLEAR->RocketPayloadType.NUCLEAR_ICBM;};}}